// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/apps", wrapper.ListApps)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/apps/facets", wrapper.ListFacets)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/apps/{id}", wrapper.GetApp)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/apps/{id}/{action}", wrapper.LaunchJob)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/jobs", wrapper.ListJobs)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/jobs/{id}", wrapper.GetJob)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/jobs/{id}/log", wrapper.GetJobLog)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/jobs/{$}", wrapper.AwxListJobs)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/jobs/{id}/{$}", wrapper.AwxGetJob)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v2/jobs/{id}/job_events/{$}", wrapper.AwxListJobEvents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/logs-app/_search", wrapper.EsSearch)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/chaos/down", wrapper.ChaosDown)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/chaos/delete/{id}", wrapper.ChaosDelete)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/chaos/spawn", wrapper.ChaosSpawn)

	return m
}

